* { box-sizing: border-box; }
:root { color-scheme: dark; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; background: #17252b; color: #eef5ee; }
body { min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #294149 0, #17252b 64%); font-size: 16px; }
.card { width: min(100%, 520px); padding: clamp(24px, 6vw, 40px); border: 1px solid #40585a; border-radius: 20px; background: #203238; box-shadow: 0 24px 70px #0c171a99; }
.pixel-mark { display: grid; grid-template-columns: repeat(2, 9px); gap: 3px; width: max-content; margin-bottom: 22px; transform: rotate(-8deg); }
.pixel-mark span { width: 9px; height: 9px; background: #f2b84b; border-radius: 2px; }
.pixel-mark span:nth-child(2), .pixel-mark span:nth-child(3) { background: #71d6b0; }
.eyebrow { margin: 0 0 8px; color: #71d6b0; font-size: 12px; font-weight: 750; letter-spacing: .14em; }
h1 { margin: 0; font-size: clamp(30px, 8vw, 40px); line-height: 1.12; letter-spacing: -.04em; }
.intro { margin: 12px 0 28px; color: #b9c9c6; line-height: 1.55; }
label { display: block; margin-bottom: 9px; color: #eef5ee; font-size: 15px; font-weight: 650; }
textarea { display: block; width: 100%; min-height: 112px; resize: vertical; padding: 14px 15px; border: 1px solid #52696a; border-radius: 11px; outline: none; background: #17272d; color: #eef5ee; font: inherit; line-height: 1.5; }
textarea::placeholder { color: #829794; }
textarea:focus, input:focus-visible { border-color: #71d6b0; box-shadow: 0 0 0 3px #71d6b033; }
#shift { width: 100%; accent-color: #71d6b0; cursor: pointer; }
.shift-row { display: flex; align-items: center; gap: 16px; }
#shiftValue { display: grid; place-items: center; width: 42px; height: 38px; border: 1px solid #52696a; border-radius: 9px; color: #f2b84b; font-weight: 750; font-variant-numeric: tabular-nums; }
.range-ends { display: flex; justify-content: space-between; margin: 2px 57px 22px 0; color: #91a6a2; font-size: 13px; }
.actions { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin-bottom: 27px; }
.button { min-height: 50px; padding: 10px 16px; border: 1px solid transparent; border-radius: 10px; font: inherit; font-weight: 750; cursor: pointer; transition: transform .12s ease, background .12s ease, box-shadow .12s ease; }
.button-primary { background: #71d6b0; color: #15332d; }
.button-secondary { border-color: #627b79; background: #2a4045; color: #eef5ee; }
.button:hover, .copy-button:hover { transform: translateY(-1px); }
.button-primary:hover { background: #8ae5c3; box-shadow: 0 5px 18px #71d6b033; }
.button-secondary:hover { background: #354f53; }
.button:active, .copy-button:active { transform: translateY(1px) scale(.99); }
button:focus-visible { outline: 3px solid #f2b84b; outline-offset: 3px; }
.result-heading { display: flex; align-items: baseline; justify-content: space-between; gap: 12px; }
.result-heading label { margin-bottom: 9px; }
#status { color: #91a6a2; font-size: 13px; }
#result { min-height: 112px; border-color: #48645d; background: #1a302f; }
.copy-button { margin-top: 12px; padding: 8px 0; border: 0; background: transparent; color: #71d6b0; font: inherit; font-weight: 700; cursor: pointer; }
.footnote { margin: 12px 0 0; color: #91a6a2; font-size: 13px; }
@media (max-width: 390px) { .card { padding: 23px 20px; } .actions { gap: 9px; } .button { padding-inline: 10px; } }

const message = document.getElementById('message');
const shift = document.getElementById('shift');
const shiftValue = document.getElementById('shiftValue');
const result = document.getElementById('result');
const status = document.getElementById('status');

shift.addEventListener('input', () => {
  shiftValue.value = shift.value;
  shiftValue.textContent = shift.value;
});

function transform(text, amount) {
  return [...text].map((character) => {
    const code = character.charCodeAt(0);
    const base = code >= 65 && code <= 90 ? 65 : code >= 97 && code <= 122 ? 97 : 0;
    return base ? String.fromCharCode((code - base + amount + 26) % 26 + base) : character;
  }).join('');
}

function run(direction) {
  const amount = Number(shift.value) * direction;
  result.value = transform(message.value, amount);
  status.textContent = direction === 1 ? 'Message encoded' : 'Message decoded';
}

document.getElementById('encode').addEventListener('click', () => run(1));
document.getElementById('decode').addEventListener('click', () => run(-1));
document.getElementById('copy').addEventListener('click', async () => {
  if (!result.value) {
    status.textContent = 'Nothing to copy yet';
    return;
  }
  try {
    await navigator.clipboard.writeText(result.value);
    status.textContent = 'Copied to clipboard';
  } catch {
    result.focus();
    result.select();
    status.textContent = 'Select and copy your result';
  }
});
